    "تم تنزيل الملف المشفر ومنع البطاقات المصدرة من البيع": "Encrypted file downloaded; exported cards blocked from sale",
    "تم تسجيل نتيجة المزود؛ لا تنشئ التسوية إيداعًا نقديًا تلقائيًا": "Provider decision recorded; settlement does not automatically fund a wallet",
    "حُفظت الإعدادات؛ الربط الفعلي غير متصل": "Settings saved; live integration is not connected",
    "أضيف الإشعار محليًا؛ لم يرسل إلى أجهزة خارجية": "Notification added locally; not sent to external devices",
    "حُفظ الطلب محليًا في الدعم الفني؛ لا يوجد إرسال خارجي": "Request saved locally in support; nothing sent externally",
    "لغة الواجهة": "Interface language",
