    "غير محدد": "Not specified",
    "بطاقات تجريبية غير قابلة للشحن. نجاح الطباعة يُسجل يدويًا هنا إلى حين ربط أجهزة POS.": "Demo cards cannot be redeemed. Print results are confirmed manually until POS devices are connected.",
    "استخدم بيانات تجريبية فقط؛ هذه النسخة تحفظ البيانات محليًا دون خزنة تشفير على خادم. يُقبل CSV، ويُفصل السيريال الداخلي عن سيريال المزود.": "Use demo data only. This edition stores data locally without a server vault. CSV is supported; internal and provider serials remain separate.",
    "الفئة التي لا تملك سعرًا فعالًا موجبًا لا يمكن بيعها. قيم الحدود المالية بالدينار العراقي.": "A category cannot be sold without a positive active price. Financial limits are in Iraqi dinars.",
    "العلامة التجارية والمجهز والجهة المنظمة حقول مستقلة. تكاملات API تُضبط لكل وكيل على حدة.": "Brand, supplier and organizing authority are separate fields. API integrations are configured per agent.",
    "التغييرات تمر بالمراجعة ثم اعتماد شخص ثانٍ. السعر صفر أو الأقل من أقل سعر بيع مسموح مرفوض. الاستيراد المحلي بصيغة CSV قابلة للفتح في Excel.": "Changes require review and approval by a second person. Zero prices and prices below the contract minimum are rejected. Local imports use Excel-compatible CSV files.",
    "البطاقة التي كُشف رمزها لا تعاد للمخزون بعد فشل الطباعة. إعادة الطباعة تستخدم البطاقة نفسها دون خصم جديد.": "A card with an exposed PIN never returns to available inventory after print failure. Reprinting uses the same card with no additional charge.",
    "الحجر والتصدير يخرجان البطاقات من المتاح، ويحتفظان بتكلفتها معلقة دون خصم آلي من المحفظة. التصدير التجريبي مشفر بكلمة مرور، ولا يوفر رابطًا محدود الصلاحية.": "Quarantine and export remove cards from available inventory, with their cost held pending and no automatic wallet debit. Demo exports are password-encrypted; expiring download links are not available.",
    "إضافة المخزون لا تموّل المحافظ. التحويل ينشئ قيدين متقابلين، ولا يسمح بتجاوز الرصيد أو التحويل خارج الشجرة.": "Adding inventory does not fund wallets. Transfers create balanced entries and cannot exceed the balance or leave the agent hierarchy.",
    "الإحداثيات دقيقة حسب الإدخال؛ حدود العراق مرسومة للتوضيح وليست خريطة ملاحة.": "Coordinates follow the entered data; Iraq's outline is illustrative and is not a navigation map.",
    "· التذاكر والردود محفوظة محليًا ولا تُرسل إلى جهة خارجية.": "• Tickets and replies are stored locally and are not sent externally.",
    "مبدّل الحسابات في الأعلى لاختبار نطاق الرؤية محليًا؛ لا يمثل تسجيل دخول آمنًا. المصادقة الحقيقية وصلاحيات الخادم ضمن متطلبات الربط.": "The account switcher previews access scope locally; it is not secure sign-in. Real authentication and backend authorization require server integration.",
    "هذا تمثيل لصلاحيات النموذج المحلي. منع الوصول الحقيقي يتطلب فرض الصلاحيات على الخادم في كل طلب API.": "This represents permissions in the local model. Real access control must be enforced by the server on every API request.",
    "الربط الفعلي ينتظر وثائق المزود والخادم. لا تدخل Token حقيقيًا في ملف HTML؛ تحفظ هذه الشاشة إعدادات البيئة فقط.": "Live integration awaits provider documentation and a backend. Do not enter real tokens into HTML; this screen stores environment settings only.",
    "لا تتوفر أزرار تعديل أو حذف للسجل. حفظه ضد العبث خارج الواجهة يحتاج خادمًا؛ ملف المتصفح ليس سجل تدقيق حصينًا.": "Audit entries cannot be edited or deleted through the UI. Tamper resistance requires a backend; browser storage is not a protected audit ledger.",
    "المؤشرات التالية مشتقة من بيانات النسخة المحلية. مراقبة الخوادم وقاعدة البيانات وزمن API غير متاحة دون خادم متصل.": "These metrics are derived from local data. Server, database and API latency monitoring requires a connected backend.",
    "المفاتيح أدناه تضبط محاكاة العمليات المحلية. TOTP وكلمات المرور والجلسات الموثوقة وحظر الشبكات تحتاج تنفيذًا على الخادم.": "These controls configure the local simulation. TOTP, passwords, trusted sessions and network blocking must be implemented on the server.",
    "إدارة البطاقات": "Card management",
    "مخزون منظم، دفعات واضحة، وسياسة صرف حسب تاريخ الانتهاء.": "Organized inventory, clear batches and expiry-based allocation.",
    "شبكة الوكلاء": "Agent network",
    "رؤية موحدة للوكلاء والمحافظ ونقاط البيع التابعة.": "A unified view of agents, wallets and their POS network.",
    "بيع وطباعة": "Sell & print",
    "إصدار البطاقات ومتابعة الطباعة والاستثناءات في مكان واحد.": "Issue cards and track printing and exceptions in one place.",
    "منصة تشغيل لتوزيع البطاقات الإلكترونية، تربط إدارة النظام بالوكلاء ونقاط البيع.": "An electronic-card distribution platform connecting administration, agents and POS.",
    "تطبيقات الهاتف وروابط المتاجر تضاف عند توفير النسخ المنشورة.": "Mobile apps and store links will be added when released.",
    "النسخة الاحتياطية تشمل البيانات التجريبية ورموز البطاقات المحلية. لا تستخدم بيانات حقيقية. الاستعادة تستبدل مساحة العمل الحالية بعد فحص الملف وتأكيدك.": "Backups contain demo data and local card codes. Do not use real data. After validation and confirmation, restoring replaces the current workspace.",
    "الفحص يمنع PIN المكرر والسيريال المكرر للفئة نفسها، ويرفض الحقول الناقصة والتواريخ المنتهية.": "Validation rejects duplicate PINs and category serials, missing fields and expired dates.",
    "ستُمنع بطاقات الدفعة من البيع. لا يمكن إلغاء دفعة استخدمت منها أي بطاقة.": "These cards will be blocked from sale. A batch with any used card cannot be cancelled.",
