    "الصلاحيات مطبقة داخل النسخة المحلية. الحماية بين مستخدمين حقيقيين تتطلب مصادقة وفرض هذه القواعد على الخادم.": "Permissions apply within this local version. Multi-user security requires authentication and server-side enforcement.",
    "منح الإجراء لا يمنح الوصول إلى وكلاء خارج النطاق المحدد.": "Granting an action does not grant access to agents outside the assigned scope.",
    "القالب يستبدل تخصيصات المسودة. لا تحفظ التغييرات إلا بعد مراجعتها وتأكيدها.": "The template replaces draft overrides. Changes are saved only after review and confirmation.",
    "عرض فقط: لا يمكن تعديل حسابك الحالي أو حساب مدير النظام.": "Read only: your current account and system owners cannot be edited here.",
    "رؤية تفصيلية للمبيعات والمخزون والمحافظ والشبكة والتشغيل ضمن صلاحيات حسابك.": "Detailed sales, inventory, wallets, network and operations within your access scope.",
    "التاريخ يرشح الحركات. الحالة تخص المبيعات فقط. المنتج والمزود يرشحان المبيعات والمخزون والأسعار. المخزون والشبكة والإعدادات لقطات حالية.": "Dates filter activity; status filters sales only. Product and provider filter sales, inventory and prices. Inventory, network and settings are current snapshots.",
    "الفلاتر الزمنية تخص الحركات؛ المخزون والشبكة والإعدادات تعرض الوضع الحالي. لا يتضمن التقرير رموز البطاقات.": "Date filters apply to activity. Inventory, network and settings show current state. Card codes are excluded.",
    "الفترة والحالة تخصان عمليات البيع؛ الربح إجمالي قبل المصاريف التشغيلية.": "Date and status filters apply to sales. Gross profit is before operating expenses.",
    "لقطة المخزون الحالية عند إنشاء التقرير؛ لا تمثل رصيدًا تاريخيًا عند نهاية الفترة.": "Current inventory at generation time; not a historical period-end balance.",
    "المحافظ مستقلة عن المخزون. التحويلات الداخلية لا تمثل إيرادًا؛ لا تجمع الوارد كصافي مبيعات.": "Wallets are separate from inventory. Internal transfers are not revenue; credits are not net sales.",
    "السجلات الحالية ضمن النطاق.": "Current records within scope.",
    "الأسعار الحالية؛ لا تطبق عليها فترة البيع.": "Current prices; sales date range does not apply.",
    "لا يتضمن التقرير رموز PIN أو كلمات التشفير.": "The report excludes PINs and encryption passwords.",
    "يعرض سجل النشاط دون تضمين قيم الحقول الحساسة.": "Activity log without sensitive field values.",
    "إعدادات حالية وليست سجلًا تاريخيًا.": "Current settings, not historical configuration.",
