    "تحكم بكل إجراء، وحدد نطاق البيانات لكل موظف. المنع المخصص يتقدم على صلاحيات الدور.": "هەر کردارێک و مەودای داتای هەر کارمەندێک دیاری بکە. قەدەغەی تایبەت پێش دەسەڵاتی ڕۆڵ دەکەوێت.",
    "الصلاحيات مطبقة داخل النسخة المحلية. الحماية بين مستخدمين حقيقيين تتطلب مصادقة وفرض هذه القواعد على الخادم.": "دەسەڵاتەکان لەم وەشانە ناوخۆییە جێبەجێ دەکرێن. پاراستنی فرەبەکارهێنەر پێویستی بە پشتڕاستکردنەوە و جێبەجێکردنی یاساکان لە سێرڤەر هەیە.",
    "منح الإجراء لا يمنح الوصول إلى وكلاء خارج النطاق المحدد.": "ڕێگەدان بە کردارێک دەستگەیشتن بە بریکارانی دەرەوەی مەودای دیاریکراو نادات.",
    "القالب يستبدل تخصيصات المسودة. لا تحفظ التغييرات إلا بعد مراجعتها وتأكيدها.": "قاڵبەکە جێی تایبەتمەندییەکانی ڕەشنووس دەگرێتەوە. گۆڕانکاری تەنها دوای پێداچوونەوە و پەسەندکردن پاشەکەوت دەکرێت.",
    "عرض فقط: لا يمكن تعديل حسابك الحالي أو حساب مدير النظام.": "تەنها بینین: هەژماری ئێستات یان بەڕێوەبەری سیستەم لێرە ناگۆڕدرێت.",
    "رؤية تفصيلية للمبيعات والمخزون والمحافظ والشبكة والتشغيل ضمن صلاحيات حسابك.": "بینینی وردی فرۆشتن، کۆگا، جزدان، تۆڕ و کارکردن لە مەودای دەسەڵاتەکانت.",
    "التاريخ يرشح الحركات. الحالة تخص المبيعات فقط. المنتج والمزود يرشحان المبيعات والمخزون والأسعار. المخزون والشبكة والإعدادات لقطات حالية.": "بەروار مامەڵەکان دەپالێوێت؛ دۆخ تەنها بۆ فرۆشتنە. بەرهەم و دابینکەر بۆ فرۆشتن و کۆگا و نرخەکانن. کۆگا و تۆڕ و ڕێکخستنەکان دۆخی ئێستان.",
    "الفلاتر الزمنية تخص الحركات؛ المخزون والشبكة والإعدادات تعرض الوضع الحالي. لا يتضمن التقرير رموز البطاقات.": "پاڵاوتنی کات بۆ مامەڵەکانە. کۆگا و تۆڕ و ڕێکخستنەکان دۆخی ئێستا نیشان دەدەن. کۆدی کارت لە ڕاپۆرتدا نییە.",
    "الفترة والحالة تخصان عمليات البيع؛ الربح إجمالي قبل المصاريف التشغيلية.": "بەروار و دۆخ بۆ فرۆشتنن. قازانج پێش خەرجییەکانی کارکردنە.",
    "لقطة المخزون الحالية عند إنشاء التقرير؛ لا تمثل رصيدًا تاريخيًا عند نهاية الفترة.": "دۆخی کۆگای ئێستا لە کاتی ڕاپۆرت؛ باڵانسی مێژوویی کۆتایی ماوە نییە.",
    "المحافظ مستقلة عن المخزون. التحويلات الداخلية لا تمثل إيرادًا؛ لا تجمع الوارد كصافي مبيعات.": "جزدانەکان لە کۆگا جیان. گواستنەوەی ناوخۆ داهات نییە؛ هاتوو فرۆشتنی خالص نییە.",
    "السجلات الحالية ضمن النطاق.": "تۆمارەکانی ئێستا لە مەودای دیاریکراو.",
    "الأسعار الحالية؛ لا تطبق عليها فترة البيع.": "نرخەکانی ئێستا؛ ماوەی فرۆشتن کاریگەری نییە.",
    "لا يتضمن التقرير رموز PIN أو كلمات التشفير.": "ڕاپۆرت کۆدی PIN و وشەی نهێنی کۆدکردن ناگرێتەوە.",
    "يعرض سجل النشاط دون تضمين قيم الحقول الحساسة.": "تۆماری چالاکی بەبێ بەهای خانە هەستیارەکان.",
    "إعدادات حالية وليست سجلًا تاريخيًا.": "ڕێکخستنی ئێستا، نەک مێژوویی.",
    "فصل أرباح مراحل البيع": "قازانج بەپێی قۆناغی فرۆشتن",
    "ربح / إيراد ماسال عند تحميل الدفعات": "قازانج / داهاتی ماساڵ لە کاتی تۆمارکردنی کۆمەڵە",
    "أرباح الوكلاء على البطاقات الصادرة": "قازانجی بریکار لە کارتە دەرکراوەکان",
    "أرباح نقاط البيع": "قازانجی خاڵی فرۆشتن",
    "هذه مجاميع السجلات الحالية في نطاقك. هامش النقطة يتطلب إدخال سعر البيع النهائي للزبون عند الإصدار؛ الدفعات القديمة لم تُفوتر بأثر رجعي.": "کۆی تۆمارەکانی ئێستا لە مەودای تۆ. قازانجی خاڵ بەپێی نرخی کۆتایی کڕیارە. بۆ کۆمەڵە کۆنەکان پسوولەی پاشەکشە دروست نەکراوە.",
    "أرصدة الخدمات والتمويل": "باڵانس و دابینکردنی خزمەتگوزارییەکان",
    "رصيد البطاقات مصدره تحميل المخزون. لكل خدمة محفظتها؛ لا يجري تعويض رصيد خدمة من أخرى.": "باڵانسی کارت لە بارکردنی کۆگا دروست دەبێت. هەر خزمەتگوزارییەک جزدانێکی جیاوازی هەیە.",
