    "الفروع المباشرة ونقاط البيع بكامل شبكة الحساب · يظهر الوكيل المباشر بجانب كل نقطة": "لقە ڕاستەوخۆکان و خاڵەکانی تۆڕی هەژمار · بریکاری ڕاستەوخۆ لە تەنیشت هەر خاڵێکە",
    "الوكلاء · الصفحة": "بریکارەکان · لاپەڕە",
    "حدد المستفيدين وأدخل مبلغ كل واحد، ثم اضغط معاينة المجموعة. المحفظة المستخدمة:": "سوودمەندەکان هەڵبژێرە و بڕی هەر یەک بنووسە، پاشان کۆمەڵەکە پێشبینین بکە. جزدانی بەکارهاتوو:",
    "رصيد البطاقات يجهّز بطلبية مخزون معتمدة بنفس القيمة.": "باڵانسی کارت بە داواکارییەکی پەسەندکراوی کۆگا بە هەمان بەها دابین دەکرێت.",
    "الرصيد يُضاف عند اعتماد الطلبية. ربطها هنا لا يضيف رصيدًا ثانيًا.": "باڵانس لە کاتی پەسەندکردنی داواکاری زیاد دەکرێت. بەستنەوەی لێرە باڵانس دووبارە زیاد ناکات.",
    "الصورة اختيارية؛ بدون صورة يظهر العنوان والتفاصيل بخلفية التصميم.": "وێنە ئارەزوومەندانەیە؛ بەبێ وێنە ناونیشان و وردەکاری لەسەر پاشبنەمای دیزاین دەردەکەون.",
    "هذا القسم مخفي. فعّل «إظهار القسم» ليظهر محتواه في البروفايل.": "ئەم بەشە شاراوەیە. «پیشاندانی بەش» چالاک بکە بۆ دەرکەوتنی ناوەڕۆکەکە لە پڕۆفایل.",
    "اختر حد الكمية أو الحد المالي ليظهر حقل القيمة. سيُطبّق حد واحد فقط.": "سنووری ژمارە یان دارایی هەڵبژێرە بۆ دەرکەوتنی خانەی بەها. تەنها یەک سنوور جێبەجێ دەکرێت.",
    "التاريخ والمرجع للسجلات؛ الأرصدة المعروضة حالية.": "بەروار و سەرچاوە بۆ پاڵاوتنی تۆمارەکانن؛ باڵانسە پیشاندراوەکان هی ئێستان.",
    "البطاقات المرفوضة لا تدخل المخزون. راجع أسباب الرفض في الجدول أدناه.": "کارتە ڕەتکراوەکان ناچنە کۆگا. هۆکاری ڕەتکردنەوە لە خشتەی خوارەوە ببینە.",
    "يوجد ملف بلا بطاقات صالحة؛ راجع أسباب الرفض ثم صححه أو أزله.": "فایلێک هیچ کارتی دروستی نییە؛ هەڵەکان ببینە، پاشان چاکی بکەوە یان لای ببە.",
    "بانتظار تسجيل نتيجة المحاولة الحالية. لا تبدأ طباعة ثانية قبل حسم النتيجة.": "چاوەڕوانی تۆمارکردنی ئەنجامی هەوڵی ئێستا. پێش تۆمارکردنی ئەنجام دووبارە چاپ مەکە.",
    "تم بلوغ الحد؛ اطلب موافقة إعادة الطباعة.": "سنوور پڕ بووە؛ داوای مۆڵەتی دووبارەچاپ بکە.",
    "◆ وكيل · ■ فرع · ▲ نقطة · ● موظف": "◆ بریکار · ■ لق · ▲ خاڵ · ● کارمەند",
    "مشاركة موقع جهازك مع الإدارة مطلوبة لاستخدام الحساب وإظهاره على الخريطة.": "هاوبەشکردنی شوێنی ئامێر لەگەڵ بەڕێوەبەرایەتی بۆ بەکارهێنانی هەژمار و پیشاندانی لە نەخشە پێویستە.",
    "اسمح للموقع من إعدادات المتصفح، وتأكد من تشغيل خدمة الموقع بالجهاز، ثم اضغط تفعيل الموقع.": "مۆڵەتی شوێن لە ڕێکخستنی وێبگەڕ بدە، خزمەتگوزاری شوێنی ئامێر چالاک بکە، پاشان چالاککردنی شوێن هەڵبژێرە.",
    "سيُخفى الحساب ويتوقف تسجيل دخوله، مع الاحتفاظ ببياناته وسجلاته.": "هەژمار دەشاردرێتەوە و چوونەژوورەوەی ڕادەگیرێت، بە پاراستنی داتا و تۆمارەکانی.",
    "وضع تجربة محلي — الرمز 123456. لم تُرسل رسالة واتساب.": "دۆخی تاقیکردنەوەی ناوخۆ — کۆد 123456. هیچ نامەی واتساپ نەنێردراوە.",
    "8 أحرف على الأقل، تتضمن حرفًا إنكليزيًا ورقمًا.": "لانیکەم 8 پیت، لەگەڵ پیتێکی ئینگلیزی و ژمارەیەک.",
    "د.ع. لا يوجد إرجاع نقدي تلقائي.": "دینار. هیچ گەڕاندنەوەیەکی خۆکاری نەخت نییە.",
